-- ARC · Richard: ejercicios nuevos, alta, rutina y dieta (app gratis por ser asesorado)
alter table public.coach_clients add column if not exists diet jsonb;

insert into public.content_exercises (id, grp, name, muscle, equip, simple, tip, unit, sort) values
  ('ARC-098', 'Espalda', 'Jalón al pecho agarre neutro', 'Dorsal ancho', 'Polea', 'Tiras del agarre neutro (palmas enfrentadas) desde arriba hacia el pecho, con las piernas ancladas.', 'Primero lleva los hombros abajo y luego los codos hacia el suelo, sin echarte hacia atrás.', '', 820),
  ('ARC-099', 'Cuádriceps', 'Prensa 45º', 'Cuádriceps, glúteo', 'Máquina', 'Con la espalda y el glúteo pegados al respaldo, bajas la plataforma doblando las rodillas y empujas hasta casi estirar las piernas.', 'Baja en 2-3 segundos, pausa de 1 segundo abajo y empuja fuerte sin bloquear las rodillas ni despegar el glúteo.', '', 821),
  ('ARC-100', 'Gemelo', 'Gemelo sentado en máquina', 'Sóleo, gemelo', 'Máquina', 'Con el peso sobre las rodillas y la punta de los pies en el borde, bajas los talones y subes de puntillas.', 'Recorrido completo: estira bien abajo y aprieta 1 segundo arriba.', '', 822),
  ('ARC-101', 'Pecho', 'Press inclinado con mancuernas', 'Pectoral superior, hombro anterior, tríceps', 'Mancuernas + banco', 'En un banco a 30-45º, bajas las mancuernas hacia la parte alta del pecho y empujas hacia arriba.', 'Si inclinas más el banco trabaja más el hombro. Omóplatos juntos y bajada controlada.', '', 823),
  ('ARC-102', 'Bíceps', 'Curl de bíceps con mancuernas', 'Bíceps braquial', 'Mancuernas', 'De pie con una mancuerna en cada mano, doblas los codos subiendo las mancuernas y bajas despacio.', 'Codos pegados al cuerpo y sin balancearte; baja estirando del todo.', '', 824),
  ('ARC-103', 'Hombro', 'Pájaros con mancuernas', 'Deltoide posterior, espalda alta', 'Mancuernas', 'Con el torso inclinado hacia delante y las mancuernas bajo los hombros, abres los brazos hacia los lados.', 'Brazos casi estirados y piensa en alejar las manos, sin subir los hombros.', '', 825),
  ('ARC-104', 'Abdomen', 'Crunch en polea de rodillas', 'Recto abdominal', 'Polea', 'De rodillas frente a la polea alta con la cuerda junto a la cabeza, encoges el tronco llevando los codos hacia las rodillas.', 'El movimiento sale del abdomen, no de los brazos ni de la cadera. Aguanta 1 segundo abajo.', '', 826),
  ('ARC-105', 'Abdomen', 'Plancha', 'Core, abdomen, hombro', 'Peso corporal', 'Apoyas antebrazos y puntas de los pies y mantienes el cuerpo recto, sin hundir la cadera.', 'Glúteos y abdomen apretados, respira con normalidad.', 's', 827)
on conflict (id) do nothing;

insert into public.coach_clients (coach_id, email, name)
select c.id, 'patinorichardmascaraque@gmail.com', 'Richard'
from (select id from public.profiles where role = 'coach' order by created_at nulls last limit 1) c
on conflict (coach_id, email) do update set name = excluded.name, updated_at = now();

